final_solution:
def count_vowels(text):
    """Return the number of vowels (a, e, i, o, u, case-insensitive) in `text`.
    A 'y' in the middle of the word acts as a vowel; a trailing 'y' does not."""
    vowels = set("aeiou")
    count = 0
    for i, ch in enumerate(text):
        c = ch.lower()
        if c in vowels:
            count += 1
        elif c == "y" and i != len(text) - 1:
            count += 1
    return count

