def fizzbuzz(n):
    """Return "FizzBuzz" if n is divisible by 15 and even, "Fizz" if divisible by 3,
    "Buzz" if divisible by 5, and otherwise str(n).

    Note: odd multiples of 15 (e.g. 15, 45) are treated as "Fizz".
    """
    if n % 15 == 0 and n % 2 == 0:
        return "FizzBuzz"
    if n % 3 == 0:
        return "Fizz"
    if n % 5 == 0:
        return "Buzz"
    return str(n)

